B.auU=new A.a("\u062b\u0645 \u0623\u0630\u0646 \u062b\u0645 \u0623\u0642\u0627\u0645 \u0641\u0635\u0644\u0649 \u0627\u0644\u0638\u0647\u0631 \u062b\u0645 \u0623\u0642\u0627\u0645 \u0641\u0635\u0644\u0649 \u0627\u0644\u0639\u0635\u0631 \u0648\u0644\u0645 \u064a\u0635\u0644 \u0628\u064a\u0646\u0647\u0645\u0627 \u0634\u064a\u0626\u0627\u064b\u060c \u062b\u0645 \u0631\u0643\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062d\u062a\u0649 \u0623\u062a\u0649 \u0627\u0644\u0645\u0648\u0642\u0641\u060c \u0641\u062c\u0639\u0644 \u0628\u0637\u0646 \u0646\u0627\u0642\u062a\u0647 \u0627\u0644\u0642\u0635\u0648\u0627\u0621 \u0625\u0644\u0649 \u0627\u0644\u0635\u062e\u0631\u0627\u062a\u060c \u0648\u062c\u0639\u0644 \u062c\u0628\u0644 \u0627\u0644\u0645\u0634\u0627\u0629 \u0628\u064a\u0646 \u064a\u062f\u064a\u0647\u060c \u0648\u0627\u0633\u062a\u0642\u0628\u0644 \u0627\u0644\u0642\u0628\u0644\u0629 \u0641\u0644\u0645 \u064a\u0632\u0644 \u0648\u0627\u0642\u0641\u0627\u064b \u062d\u062a\u0649 \u063a\u0631\u0628\u062a \u0627\u0644\u0634\u0645\u0633 \u0648\u0630\u0647\u0628\u062a \u0627\u0644\u0635\u0641\u0631\u0629 \u0642\u0644\u064a\u0644\u0627\u064b \u062d\u062a\u0649 \u063a\u0627\u0628 \u0627\u0644\u0642\u0631\u0635\u060c \u0648\u0630\u0643\u0631 \u0623\u0628\u0648 \u0627\u0644\u062d\u0633\u0646 \u0627\u0644\u0646\u062f\u0648\u064a: \u0644\u0645\u0627 \u0641\u0631\u063a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0646 \u0635\u0644\u0627\u062a\u0647 \u0648\u0627\u0644\u062a\u0636\u0631\u0639 \u0648\u0627\u0644\u0627\u0628\u062a\u0647\u0627\u0644 \u0625\u0644\u0649 \u063a\u0631\u0648\u0628 \u0627\u0644\u0634\u0645\u0633 \u0648\u0643\u0627\u0646 \u0641\u064a \u062f\u0639\u0627\u0626\u0647 \u0631\u0627\u0641\u0639\u0627\u064b \u064a\u062f\u064a\u0647 \u0625\u0644\u0649 \u0635\u062f\u0631\u0647 \u0643\u0627\u0633\u062a\u0637\u0639\u0627\u0645 \u0627\u0644\u0645\u0633\u0643\u064a\u0646 \u064a\u0642\u0648\u0644 \u0641\u064a\u0647: \u0627\u0644\u0644\u0647\u0645 \u0625\u0646\u0643 \u062a\u0633\u0645\u0639 \u0643\u0644\u0627\u0645\u064a \u0648\u062a\u0631\u0649 \u0645\u0643\u0627\u0646\u064a \u0648\u062a\u0639\u0644\u0645 \u0633\u0631\u064a \u0648\u0639\u0644\u0627\u0646\u064a\u062a\u064a \u0644\u0627\u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0643 \u0634\u064a\u0621 \u0645\u0646 \u0623\u0645\u0631\u064a\u060c \u0623\u0646\u0627 \u0627\u0644\u0628\u0627\u0626\u0633 \u0627\u0644\u0641\u0642\u064a\u0631 \u0627\u0644\u0645\u0633\u062a\u063a\u064a\u062b \u0627\u0644\u0645\u0633\u062a\u062c\u064a\u0631\u060c \u0648\u0627\u0644\u0648\u062c\u0644 \u0627\u0644\u0645\u0634\u0641\u0642 \u0627\u0644\u0645\u0642\u0631 \u0627\u0644\u0645\u0639\u062a\u0631\u0641 \u0628\u0630\u0646\u0648\u0628\u064a\u060c \u0623\u0633\u0623\u0644\u0643 \u0645\u0633\u0623\u0644\u0629 \u0627\u0644\u0645\u0633\u0643\u064a\u0646\u060c \u0648\u0623\u0628\u062a\u0647\u0644 \u0625\u0644\u064a\u0643 \u0627\u0628\u062a\u0647\u0627\u0644 \u0627\u0644\u0645\u0630\u0646\u0628 \u0627\u0644\u0630\u0644\u064a\u0644\u060c \u0648\u0623\u062f\u0639\u0648\u0643 \u062f\u0639\u0627\u0621 \u0627\u0644\u062e\u0627\u0626\u0641 \u0627\u0644\u0636\u0631\u064a\u0631 \u0645\u0646 \u062e\u0636\u0639\u062a \u0644\u0643 \u0631\u0642\u0628\u062a\u0647 \u0648\u0641\u0627\u0636\u062a \u0644\u0643 \u0639\u064a\u0646\u0627\u0647 \u0648\u0630\u0644 \u062c\u0633\u062f\u0647 \u0648\u0631\u063a\u0645 \u0623\u0646\u0641\u0647 \u0644\u0643\u060c \u0627\u0644\u0644\u0647\u0645 \u0644\u0627\u062a\u062c\u0639\u0644\u0646\u064a \u0628\u062f\u0639\u0627\u0626\u0643 \u0631\u0628 \u0634\u0642\u064a\u0627\u060c \u0648\u0643\u0646 \u0628\u064a \u0631\u0624\u0648\u0641\u0627\u064b \u0631\u062d\u064a\u0645\u0627\u064b \u064a\u0627\u062e\u064a\u0631 \u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0646 \u0648\u064a\u0627\u062e\u064a\u0631 \u0627\u0644\u0645\u0639\u0637\u064a\u0646.",null)
