B.az4=new A.a("\u0648\u0644\u0647\u0630\u0627 \u0627\u0642\u062a\u0636\u062a \u0627\u0644\u062d\u0643\u0645\u0629 \u0627\u0644\u0625\u0644\u0647\u064a\u0629 \u0648\u0627\u0644\u0631\u062d\u0645\u0629 \u0627\u0644\u0631\u0628\u0627\u0646\u064a\u0629 \u0623\u0644\u0627 \u064a\u062c\u0627\u0628\u0648\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0633\u0623\u0644\u0648\u0627\u060c \u0644\u0623\u0646 \u0633\u0646\u062a\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0623\u0646\u0647 \u0625\u0630\u0627 \u0637\u0644\u0628 \u0642\u0648\u0645 \u0622\u064a\u0627\u062a \u0641\u0623\u062c\u064a\u0628\u0648\u0627\u060c \u062b\u0645 \u0644\u0645 \u064a\u0624\u0645\u0646\u0648\u0627\u060c \u0639\u0630\u0651\u064e\u0628\u0647\u0645 \u0639\u0630\u0627\u0628 \u0627\u0644\u0627\u0633\u062a\u0626\u0635\u0627\u0644 \u0643\u0645\u0627 \u0641\u0639\u0644 \u0628\u0639\u0627\u062f \u0648\u062b\u0645\u0648\u062f \u0648\u0642\u0648\u0645 \u0641\u0631\u0639\u0648\u0646.",null)
B.asU=new A.a("\u0648\u0642\u062f \u0630\u0643\u0631 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0639\u0628\u0627\u0633 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0631\u0648\u0627\u064a\u0629 \u0645\u0641\u0627\u062f\u0647\u0627: \u0623\u0646 \u0642\u0631\u064a\u0634\u0627 \u0642\u0627\u0644\u062a \u0644\u0644\u0646\u0628\u064a \ufdfa \u0627\u062f\u0639\u064f \u0644\u0646\u0627 \u0631\u0628\u0643 \u0623\u0646 \u064a\u062c\u0639\u0644 \u0644\u0646\u0627 \u0627\u0644\u0635\u0641\u0627 \u0630\u0647\u0628\u064b\u0627 \u0648\u0646\u0624\u0645\u0646 \u0628\u0643\u060c \u0642\u0627\u0644: \u0648\u062a\u0641\u0639\u0644\u0648\u0646\u061f \u0642\u0627\u0644\u0648\u0627: \u0646\u0639\u0645\u060c \u0642\u0627\u0644 \u0641\u062f\u0639\u0627\u0647: \u0641\u0623\u062a\u0627\u0647 \u062c\u0628\u0631\u064a\u0644 \u0641\u0642\u0627\u0644: \u0625\u0646 \u0631\u0628\u0643 -\u0639\u0632 \u0648\u062c\u0644- \u064a\u0642\u0631\u0623 \u0639\u0644\u064a\u0643 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u064a\u0642\u0648\u0644 \u0625\u0646 \u0634\u0626\u062a \u0623\u0635\u0628\u062d \u0644\u0647\u0645 \u0627\u0644\u0635\u0641\u0627 \u0630\u0647\u0628\u064b\u0627\u060c \u0641\u0645\u0646 \u0643\u0641\u0631 \u0628\u0639\u062f \u0630\u0644\u0643 \u0645\u0646\u0647\u0645 \u0639\u0630\u0628\u062a\u0647 \u0639\u0630\u0627\u0628\u064b\u0627 \u0644\u0627 \u0623\u0639\u0630\u0628\u0647 \u0623\u062d\u062f\u064b\u0627 \u0645\u0646 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646\u060c \u0648\u0625\u0646 \u0634\u0626\u062a \u0641\u062a\u062d\u062a \u0644\u0647\u0645 \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u062a\u0648\u0628\u0629\u060c \u0648\u0627\u0644\u0631\u062d\u0645\u0629\u060c \u0641\u0642\u0627\u0644: \u0628\u0644 \u0628\u0627\u0628 \u0627\u0644\u062a\u0648\u0628\u0629 \u0648\u0627\u0644\u0631\u062d\u0645\u0629\u060c \u0641\u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e\u0646\u064e\u0627 \u0623\u064e\u0646 \u0646\u0651\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0628\u0650\u0627\u0644\u0622\u064e\u064a\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u0627\u0651\u064e \u0623\u064e\u0646 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0647\u064e\u0627 \u0627\u0644\u0623\u0648\u0651\u064e\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0642\u064e\u0629\u064e \u0645\u064f\u0628\u0652\u0635\u0650\u0631\u064e\u0629\u064b \u0641\u064e\u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0631\u0652\u0633\u0650\u0644\u064f \u0628\u0650\u0627\u0644\u0622\u064e\u064a\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u0627\u0651\u064e \u062a\u064e\u062e\u0652\u0648\u0650\u064a\u0641\u064b\u0627 - \u0633\u0648\u0631\u0629 \u0627\u0644\u0625\u0633\u0631\u0627\u0621",null)
B.aZK=new A.a("\u064a\u0639\u0646\u064a \u0644\u0648 \u0623\u0646 \u0647\u0646\u0627\u0643 \u0642\u0631\u0622\u0646\u0627 \u0628\u0647\u0630\u0647 \u0627\u0644\u0645\u062b\u0627\u0628\u0629 \u0644\u0643\u0627\u0646 \u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645\u060c \u0641\u0647\u0648 \u0644\u064a\u0633 \u0644\u0647 \u0645\u062b\u064a\u0644 \u0644\u0627 \u0645\u0646 \u0642\u0628\u0644 \u0648\u0644\u0627 \u0645\u0646 \u0628\u0639\u062f\u060c \u062c\u0648\u0627\u0628 \u0644\u0648 \u0645\u062d\u0630\u0648\u0641 \u062f\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0645\u0642\u0627\u0645.",null)
B.azw=new A.a("\u0644\u0642\u062f \u0643\u0627\u0646 \u0647\u062f\u0641 \u0632\u0639\u0645\u0627\u0621 \u0642\u0631\u064a\u0634 \u0645\u0646 \u062a\u0644\u0643 \u0627\u0644\u0645\u0637\u0627\u0644\u0628\u060c \u0647\u0648 \u0634\u0646 \u062d\u0631\u0628 \u0625\u0639\u0644\u0627\u0645\u064a\u0629 \u0636\u062f \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u0627\u0644\u062f\u0627\u0639\u064a\u0629\u060c \u0648\u0627\u0644\u062a\u0622\u0645\u0631 \u0639\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u0643\u064a \u062a\u0628\u062a\u0639\u062f \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0639\u0646\u0647 \ufdfa \u0644\u0623\u0646\u0647\u0645 \u064a\u0637\u0627\u0644\u0628\u0648\u0646 \u0628\u0623\u0645\u0648\u0631 \u064a\u062f\u0631\u0643\u0648\u0646 \u0623\u0646\u0647\u0627 \u0644\u064a\u0633\u062a \u0637\u0628\u064a\u0639\u0629 \u0647\u0630\u0647 \u0627\u0644\u062f\u0639\u0648\u0629\u061b \u0648\u0644\u0647\u0630\u0627 \u0623\u0635\u0631\u0648\u0627 \u0639\u0644\u064a\u0647\u0627\u060c \u0628\u0644 \u0644\u0642\u062f \u0635\u0631\u062d\u0648\u0627 \u0628\u0623\u0646 \u0644\u0648 \u062a\u062d\u0642\u0642 \u0634\u064a\u0621 \u0645\u0646 \u0630\u0644\u0643 \u0641\u0644\u0646 \u064a\u0624\u0645\u0646\u0648\u0627 \u0623\u064a\u0636\u0627 \u0628\u0647\u0630\u0647 \u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0648\u0647\u0630\u0627 \u0643\u0644\u0647 \u0645\u062d\u0627\u0648\u0644\u0629 \u0645\u0646\u0647\u0645 \u0644\u0625\u0638\u0647\u0627\u0631 \u0639\u062c\u0632 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0648\u0627\u062a\u062e\u0627\u0630 \u0630\u0644\u0643 \u0630\u0631\u064a\u0639\u0629 \u0644\u0645\u0646\u0639 \u0627\u0644\u0646\u0627\u0633 \u0639\u0646 \u0627\u062a\u0628\u0627\u0639\u0647.",null)
