B.aVL=new A.a("\u0643\u0627\u0646 \u0628\u0646\u0648 \u0639\u0645\u0631\u0648 \u0644\u0626\u0627\u0645\u064b\u0627 \u0641\u0644\u0645 \u064a\u0643\u062a\u0645\u0648\u0627 \u062e\u0628\u0631 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0628\u0644 \u0623\u063a\u0631\u0648\u0627 \u0628\u0647 \u0633\u0641\u0647\u0627\u0621\u0647\u0645 \u0648\u0639\u0628\u064a\u062f\u0647\u0645 \u064a\u0633\u0628\u0648\u0646\u0647 \u0648\u064a\u0631\u0645\u0648\u0646 \u0639\u0631\u0627\u0642\u064a\u0628\u0647 \u0628\u0627\u0644\u062d\u062c\u0627\u0631\u0629\u060c \u062d\u062a\u0649 \u062f\u0645\u062a \u0639\u0642\u0628\u0627\u0647 \u0648\u062a\u0644\u0637\u062e\u062a \u0646\u0639\u0644\u0627\u0647\u060c \u0648\u0633\u0627\u0644 \u062f\u0645\u0647 \u0627\u0644\u0632\u0643\u064a \u0639\u0644\u0649 \u0623\u0631\u0636 \u0627\u0644\u0637\u0627\u0626\u0641\u060c \u0648\u0645\u0627 \u0632\u0627\u0644\u0648\u0627 \u0628\u0647 \u0648\u0628\u0632\u064a\u062f \u0628\u0646 \u062d\u0627\u0631\u062b\u0629 \u062d\u062a\u0649 \u0623\u0644\u062c\u0623\u0648\u0647\u0645\u0627 \u0625\u0644\u0649 \u062d\u0627\u0626\u0637- \u0628\u0633\u062a\u0627\u0646- \u0644\u0639\u062a\u0628\u0629 \u0648\u0634\u064a\u0628\u0629 \u0627\u0628\u0646\u064a \u0631\u0628\u064a\u0639\u0629\u060c \u0648\u0647\u0645\u0627 \u0641\u064a\u0647\u060c \u0641\u0643\u0631\u0647 \u0645\u0643\u0627\u0646\u0647\u0645\u0627 \u0644\u0639\u062f\u0627\u0648\u062a\u0647\u0645\u0627 \u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0631\u062c\u0639 \u0639\u0646\u0647 \u0645\u0646 \u0633\u0641\u0647\u0627\u0621 \u062b\u0642\u064a\u0641 \u0645\u0646 \u0643\u0627\u0646 \u064a\u062a\u0628\u0639\u0647.",null)
B.aVr=new A.a("\u0641\u0639\u0645\u062f \u0625\u0644\u0649 \u0638\u0644 \u0634\u062c\u0631\u0629 \u0645\u0646 \u0639\u0646\u0628 \u0641\u062c\u0644\u0633 \u0641\u064a\u0647 \u0645\u0639 \u0632\u064a\u062f\u060c \u0631\u064a\u062b\u0645\u0627 \u064a\u0633\u062a\u0631\u064a\u062d\u0627 \u0645\u0646 \u0639\u0646\u0627\u0626\u0647\u0645\u0627\u060c \u0648\u0645\u0627 \u0623\u0635\u0627\u0628\u0647\u0645\u0627\u060c \u0648\u0627\u0628\u0646\u0627 \u0631\u0628\u064a\u0639\u0629 \u064a\u0646\u0638\u0631\u0627\u0646 \u0625\u0644\u064a\u0647\u060c \u0648\u064a\u0631\u064a\u0627\u0646 \u0645\u0627 \u0644\u0642\u064a \u0645\u0646 \u0633\u0641\u0647\u0627\u0621 \u0623\u0647\u0644 \u0627\u0644\u0637\u0627\u0626\u0641\u060c \u0648\u0644\u0645 \u064a\u062d\u0631\u0643\u0627 \u0633\u0627\u0643\u0646\u064b\u0627\u060c \u0648\u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u063a\u0645\u0631\u0629 \u0645\u0646 \u0627\u0644\u0623\u0633\u0649 \u0648\u0627\u0644\u062d\u0632\u0646\u060c \u0648\u0627\u0644\u0622\u0644\u0627\u0645 \u0627\u0644\u0646\u0641\u0633\u064a\u0629 \u0648\u0627\u0644\u062c\u0633\u0645\u0627\u0646\u064a\u0629 \u062a\u0648\u062c\u0647 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0625\u0644\u0649 \u0631\u0628\u0647 \u0628\u0647\u0630\u0627 \u0627\u0644\u062f\u0639\u0627\u0621 \u0627\u0644\u0630\u064a \u064a\u0641\u064a\u0636 \u0625\u064a\u0645\u0627\u0646\u064b\u0627 \u0648\u064a\u0642\u064a\u0646\u064b\u0627\u060c \u0648\u0631\u0636\u0649 \u0628\u0645\u0627 \u0646\u0627\u0644\u0647 \u0641\u064a \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0633\u062a\u0631\u0636\u0627\u0621 \u0644\u0644\u0647 \u0641\u0642\u0627\u0644 \ufdfa :",null)
