B.aIQ=new A.a("\u0643\u0627\u0646\u062a \u0631\u062d\u0645\u062a\u0647 \u0648\u0634\u0641\u0642\u062a\u0647 \u0627\u0644\u0639\u0638\u064a\u0645\u0629 \u0647\u064a \u0627\u0644\u062a\u064a \u062a\u063a\u0644\u0628 \u0641\u064a \u0627\u0644\u0645\u0648\u0627\u0642\u0641 \u0627\u0644\u0639\u0635\u064a\u0628\u0629 \u0627\u0644\u062a\u064a \u062a\u0628\u0644\u063a \u0641\u064a\u0647\u0627 \u0627\u0644\u0645\u0639\u0627\u0646\u0627\u0629 \u0623\u0634\u062f \u0645\u0631\u0627\u062d\u0644\u0647\u0627\u060c \u0648\u062a\u0636\u063a\u0637 \u0628\u0639\u0646\u0641 \u0639\u0644\u0649 \u0627\u0644\u0646\u0641\u0633 \u0644\u062a\u0634\u062a\u062f \u0648\u062a\u0642\u0633\u0648\u060c \u0648\u0639\u0644\u0649 \u0627\u0644\u0635\u062f\u0631 \u0644\u064a\u0636\u064a\u0642 \u0648\u064a\u062a\u0628\u0631\u0645\u060c \u0648\u0645\u0639 \u0630\u0644\u0643 \u062a\u0628\u0642\u0649 \u0646\u0641\u0633\u0647 \u0627\u0644\u0643\u0628\u064a\u0631\u0629 \u0648\u0631\u062d\u0645\u062a\u0647 \u0627\u0644\u0639\u0638\u064a\u0645\u0629 \u0647\u064a \u0627\u0644\u063a\u0627\u0644\u0628\u0629.",null)
B.aLq=new A.a("\u0641\u0639\u0646 \u0639\u0627\u0626\u0634\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 \u0632\u0648\u062c \u0627\u0644\u0646\u0628\u064a \ufdfa \u0623\u0646\u0647\u0627 \u0633\u0623\u0644\u062a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \u0647\u0644 \u0623\u062a\u0649 \u0639\u0644\u064a\u0643 \u064a\u0648\u0645 \u0643\u0627\u0646 \u0623\u0634\u062f \u0645\u0646 \u064a\u0648\u0645 \u0623\u062d\u062f\u061f \u0642\u0627\u0644: \u0644\u0642\u062f \u0644\u0642\u064a\u062a \u0645\u0646 \u0642\u0648\u0645\u0643 \u0645\u0627 \u0644\u0642\u064a\u062a\u060c \u0648\u0643\u0627\u0646 \u0623\u0634\u062f \u0645\u0627 \u0644\u0642\u064a\u062a \u0645\u0646\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0639\u0642\u0628\u0629\u060c \u0625\u0630 \u0639\u0631\u0636\u062a \u0646\u0641\u0633\u064a \u0639\u0644\u0649 \u0627\u0628\u0646 \u0639\u0628\u062f \u064a\u0627\u0644\u064a\u0644 \u0628\u0646 \u0639\u0628\u062f \u0643\u064f\u0644\u0627\u0644 \u0641\u0644\u0645 \u064a\u062c\u0628\u0646\u064a \u0625\u0644\u0649 \u0645\u0627 \u0623\u0631\u062f\u062a\u060c \u0641\u0627\u0646\u0637\u0644\u0642\u062a \u0648\u0623\u0646\u0627 \u0645\u0647\u0645\u0648\u0645 \u0639\u0644\u0649 \u0648\u062c\u0647\u064a\u060c \u0641\u0644\u0645 \u0623\u0633\u062a\u0641\u0642 \u0625\u0644\u0627 \u0648\u0623\u0646\u0627 \u0628\u0642\u0631\u0646 \u0627\u0644\u062b\u0639\u0627\u0644\u0628 -\u0647\u0648 \u0642\u0631\u0646 \u0627\u0644\u0645\u0646\u0627\u0632\u0644 \u0645\u064a\u0642\u0627\u062a \u0623\u0647\u0644 \u0646\u062c\u062f \u0648\u064a\u0633\u0645\u0649 \u0627\u0644\u0622\u0646 \u0627\u0644\u0633\u064a\u0644 \u0627\u0644\u0643\u0628\u064a\u0631-  \u0641\u0631\u0641\u0639\u062a \u0631\u0623\u0633\u064a \u0641\u0625\u0630\u0627 \u0623\u0646\u0627 \u0628\u0633\u062d\u0627\u0628\u0629 \u0642\u062f \u0623\u0638\u0644\u062a\u0646\u064a \u0641\u0646\u0638\u0631\u062a \u0641\u0625\u0630\u0627 \u0641\u064a\u0647\u0627 \u062c\u0628\u0631\u064a\u0644 \u0641\u0646\u0627\u062f\u0627\u0646\u064a \u0641\u0642\u0627\u0644: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0642\u062f \u0633\u0645\u0639 \u0642\u0648\u0644 \u0642\u0648\u0645\u0643 \u0644\u0643 \u0648\u0645\u0627 \u0631\u062f\u0648\u0627 \u0639\u0644\u064a\u0643\u060c \u0648\u0642\u062f \u0628\u0639\u062b \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0643 \u0645\u0644\u0643 \u0627\u0644\u062c\u0628\u0627\u0644 \u0644\u062a\u0623\u0645\u0631\u0647 \u0628\u0645\u0627 \u0634\u0626\u062a \u0641\u064a\u0647\u0645\u060c \u0641\u0646\u0627\u062f\u0627\u0646\u064a \u0645\u0644\u0643 \u0627\u0644\u062c\u0628\u0627\u0644\u060c \u0641\u0633\u0644\u0645 \u0639\u0644\u064a \u062b\u0645 \u0642\u0627\u0644: \u064a\u0627 \u0645\u062d\u0645\u062f \u0641\u0642\u0627\u0644: \u0630\u0644\u0643 \u0641\u064a\u0645\u0627 \u0634\u0626\u062a\u060c \u0625\u0646 \u0634\u0626\u062a \u0623\u0646 \u0623\u0637\u0628\u0642 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0623\u062e\u0634\u0628\u064a\u0646\u060c \u0641\u0642\u0627\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa: \u0628\u0644 \u0623\u0631\u062c\u0648 \u0623\u0646 \u064a\u062e\u0631\u062c \u0627\u0644\u0644\u0647 \u0645\u0646 \u0623\u0635\u0644\u0627\u0628\u0647\u0645 \u0645\u0646 \u064a\u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u064a\u0634\u0631\u0643\u064f \u0628\u0647 \u0634\u064a\u0626\u064b\u0627.",null)
