B.aHY=new A.a("\u0641\u0642\u062f \u0648\u0631\u062f \u0639\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u062b\u0646\u0627\u0624\u0647 \u0639\u0644\u0649 \u0645\u0644\u0643 \u0627\u0644\u062d\u0628\u0634\u0629 \u0628\u0642\u0648\u0644\u0647: \u0648\u0643\u0627\u0646 \u0628\u0627\u0644\u062d\u0628\u0634\u0629 \u0645\u0644\u0643 \u0635\u0627\u0644\u062d \u064a\u0642\u0627\u0644 \u0644\u0647 \u0627\u0644\u0646\u062c\u0627\u0634\u064a\u060c \u0644\u0627 \u064a\u0638\u0644\u0645 \u0623\u062d\u062f \u0628\u0623\u0631\u0636\u0647\u060c \u0648\u0643\u0627\u0646 \u064a\u064f\u0646\u0652\u062b\u064e\u064a \u064a\u0634\u0627\u0639 \u0639\u0644\u064a\u0647 \u0645\u0639 \u0630\u0644\u0643 \u0635\u0644\u0627\u062d\u0647  \u0648\u064a\u0638\u0647\u0631 \u0647\u0630\u0627 \u0627\u0644\u0635\u0644\u0627\u062d \u0641\u064a \u062d\u0645\u0627\u064a\u062a\u0647 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0648\u062a\u0623\u062b\u0631\u0647 \u0628\u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u0639\u0646\u062f\u0645\u0627 \u0633\u0645\u0639\u0647 \u0645\u0646 \u062c\u0639\u0641\u0631 - \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 -\u060c \u0648\u0643\u0627\u0646 \u0645\u0639\u062a\u0642\u062f\u0647 \u0641\u064a \u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0635\u062d\u064a\u062d\u064b\u0627.",null)
B.atj=new A.a("\u0625\u0646 \u0627\u0644\u062a\u062c\u0627\u0631\u0629 \u0643\u0627\u0646\u062a \u0639\u0645\u0627\u062f \u0627\u0644\u0627\u0642\u062a\u0635\u0627\u062f \u0627\u0644\u0642\u0631\u0634\u064a\u060c \u0648\u0627\u0644\u062d\u0628\u0634\u0629 \u062a\u0639\u062a\u0628\u0631 \u0645\u0646 \u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u062a\u062c\u0627\u0631\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u064a\u0631\u0629\u060c \u0641\u0631\u0628\u0645\u0627 \u0639\u0631\u0641\u0647\u0627 \u0628\u0639\u0636 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0639\u0646\u062f\u0645\u0627 \u0630\u0647\u0628\u0648\u0627 \u0625\u0644\u064a\u0647\u0627 \u0641\u064a \u0627\u0644\u062a\u062c\u0627\u0631\u0629\u060c \u0623\u0648 \u0630\u0643\u0631\u0647\u0627 \u0644\u0647\u0645 \u0645\u0646 \u0630\u0647\u0628 \u0625\u0644\u064a\u0647\u0645 \u0642\u0628\u0644\u0647\u0645\u060c \u0648\u0642\u062f \u0630\u0643\u0631 \u0627\u0644\u0637\u0628\u0631\u064a \u0641\u064a \u0645\u0639\u0631\u0636 \u0630\u0643\u0631\u0647 \u0644\u0623\u0633\u0628\u0627\u0628 \u0627\u0644\u0647\u062c\u0631\u0629 \u0644\u0644\u062d\u0628\u0634\u0629: \u0648\u0643\u0627\u0646\u062a \u0623\u0631\u0636 \u0627\u0644\u062d\u0628\u0634\u0629 \u0645\u062a\u062c\u0631\u064b\u0627 \u0644\u0642\u0631\u064a\u0634\u060c \u064a\u062a\u062c\u0631\u0648\u0646 \u0641\u064a\u0647\u0627\u060c \u064a\u062c\u062f\u0648\u0646 \u0641\u064a\u0647\u0627 \u0631\u0641\u0627\u063a\u0627 -\u0633\u0639\u0629 \u0627\u0644\u0639\u064a\u0634 - \u0645\u0646 \u0627\u0644\u0631\u0632\u0642 \u0648\u0623\u0645\u0646\u064b\u0627\u060c \u0648\u0645\u062a\u062c\u0631\u064b\u0627 \u062d\u0633\u0646\u064b\u0627.",null)
B.aT2=new A.a("\u0641\u0644\u0645 \u064a\u0643\u0646 \u0641\u064a \u062d\u064a\u0646\u0647\u0627 \u0641\u064a \u062e\u0627\u0631\u062c \u0627\u0644\u062c\u0632\u064a\u0631\u0629 \u0628\u0644\u062f \u0623\u0643\u062b\u0631 \u0623\u0645\u0646\u064b\u0627 \u0645\u0646 \u0628\u0644\u0627\u062f \u0627\u0644\u062d\u0628\u0634\u0629\u060c \u0648\u0645\u0646 \u0627\u0644\u0645\u0639\u0644\u0648\u0645 \u0628\u064f\u0639\u062f \u0627\u0644\u062d\u0628\u0634\u0629 \u0639\u0646 \u0633\u0637\u0648\u0629 \u0642\u0631\u064a\u0634 \u0645\u0646 \u062c\u0627\u0646\u0628 \u0648\u0647\u064a \u0644\u0627 \u062a\u062f\u064a\u0646 \u0644\u0642\u0631\u064a\u0634 \u0628\u0627\u0644\u0627\u062a\u0628\u0627\u0639 \u0643\u063a\u064a\u0631\u0647\u0627  \u0645\u0646 \u0627\u0644\u0642\u0628\u0627\u0626\u0644\u060c \u0648\u0641\u064a \u062d\u062f\u064a\u062b \u0627\u0628\u0646 \u0625\u0633\u062d\u0627\u0642 \u0639\u0646 \u0623\u0633\u0628\u0627\u0628 \u0627\u062a\u062e\u0627\u0630 \u0627\u0644\u062d\u0628\u0634\u0629 \u0645\u0643\u0627\u0646\u064b\u0627 \u0644\u0644\u0647\u062c\u0631\u0629 \u0623\u0646\u0647\u0627: \u0623\u0631\u0636 \u0635\u062f\u0642\u060c \u0648\u0623\u0646 \u0628\u0647\u0627 \u0645\u0644\u0643\u064b\u0627 \u0644\u0627 \u064a\u0638\u0644\u0645 \u0639\u0646\u062f\u0647 \u0623\u062d\u062f  \u0641\u0647\u064a \u0623\u0631\u0636 \u0635\u062f\u0642\u060c \u0648\u0645\u0644\u0643\u0647\u0627 \u0639\u0627\u062f\u0644\u060c \u0648\u062a\u0644\u0643 \u0645\u0646 \u0623\u0647\u0645 \u0633\u0645\u0627\u062a \u0627\u0644\u0628\u0644\u062f \u0627\u0644\u0622\u0645\u0646.",null)
