B.aYR=new A.a("\u0643\u062a\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0625\u0644\u0649 \u0646\u062c\u0631\u0627\u0646 \u0643\u062a\u0627\u0628\u0627\u064b \u0642\u0627\u0644 \u0641\u064a\u0647: \u0623\u0645\u0627 \u0628\u0639\u062f \u0641\u0625\u0646\u064a \u0623\u062f\u0639\u0648\u0643\u0645 \u0625\u0644\u0649 \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0639\u0628\u0627\u062f \u0648\u0623\u062f\u0639\u0648\u0643\u0645 \u0625\u0644\u0649 \u0648\u0644\u0627\u064a\u0629 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0648\u0644\u0627\u064a\u0629 \u0627\u0644\u0639\u0628\u0627\u062f \u0641\u0625\u0646 \u0623\u0628\u064a\u062a\u0645 \u0641\u0627\u0644\u062c\u0632\u064a\u0629\u060c \u0641\u0625\u0646 \u0623\u0628\u064a\u062a\u0645 \u0622\u0630\u0646\u062a\u0643\u0645 \u0628\u062d\u0631\u0628 \u0648\u0627\u0644\u0633\u0644\u0627\u0645.",null)
B.aQL=new A.a("\u0641\u0644\u0645\u0627 \u0623\u062a\u0649 \u0627\u0644\u0623\u0633\u0642\u0641 \u0627\u0644\u0643\u062a\u0627\u0628 \u062c\u0645\u0639 \u0627\u0644\u0646\u0627\u0633 \u0648\u0642\u0631\u0623\u0647 \u0639\u0644\u064a\u0647\u0645 \u0648\u0633\u0623\u0644\u0647\u0645 \u0639\u0646 \u0627\u0644\u0631\u0623\u064a \u0641\u064a\u0647\u061f \u0641\u0642\u0631\u0631\u0648\u0627 \u0623\u0646 \u064a\u0631\u0633\u0644\u0648\u0627 \u0625\u0644\u064a\u0647 \u0648\u0641\u062f\u0627\u064b \u064a\u062a\u0643\u0648\u0646 \u0645\u0646 \u0623\u0631\u0628\u0639\u0629 \u0639\u0634\u0631 \u0645\u0646 \u0623\u0634\u0631\u0627\u0641\u0647\u0645 \u0648\u0642\u064a\u0644 \u0633\u062a\u064a\u0646 \u0631\u0627\u0643\u0628\u0627\u064b \u0645\u0646\u0647\u0645 \u062b\u0644\u0627\u062b\u0629 \u0646\u0641\u0631 \u064a\u0624\u0648\u0644 \u0625\u0644\u064a\u0647\u0645 \u0623\u0645\u0631\u0647\u0645: \u0627\u0644\u0639\u0627\u0642\u0628 \u0648\u0647\u0648 \u0623\u0645\u064a\u0631\u0647\u0645 \u0648\u0635\u0627\u062d\u0628 \u0645\u0634\u0648\u0631\u062a\u0647\u0645 \u0648\u0627\u0644\u0630\u064a\u0646 \u064a\u0635\u062f\u0631\u0648\u0646 \u0639\u0646 \u0631\u0623\u064a\u0647 \u0648\u0627\u0644\u0633\u064a\u062f \u0648\u0647\u0648 \u0635\u0627\u062d\u0628 \u0631\u062d\u0644\u062a\u0647\u0645 \u0648\u0623\u0628\u0648 \u0627\u0644\u062d\u0627\u0631\u062b \u0623\u0633\u0642\u0641\u0647\u0645 \u0648\u062d\u0628\u0631\u0647\u0645 \u0648\u0635\u0627\u062d\u0628 \u0645\u062f\u0627\u0631\u0633\u0647\u0645\u060c \u0641\u0642\u062f\u0645\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0641\u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u0645\u0633\u062c\u062f \u0639\u0644\u064a\u0647\u0645 \u062b\u064a\u0627\u0628 \u0627\u0644\u062d\u0650\u0628\u064e\u0631\u0629 \u0648\u0623\u0631\u062f\u064a\u0629 \u0645\u0643\u0641\u0648\u0641\u0629 \u0628\u0627\u0644\u062d\u0631\u064a\u0631 \u0648\u0641\u064a \u0623\u064a\u062f\u064a\u0647\u0645 \u062e\u0648\u0627\u062a\u064a\u0645 \u0627\u0644\u0630\u0647\u0628\u060c \u0641\u0642\u0627\u0645\u0648\u0627 \u064a\u0635\u0644\u0651\u064f\u0648\u0646 \u0641\u064a \u0627\u0644\u0645\u0633\u062c\u062f \u0646\u062d\u0648 \u0627\u0644\u0645\u0634\u0631\u0642 \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u062f\u0639\u0648\u0647\u0645.",null)
