B.aCy=new A.a("\u0648\u062c\u0627\u0621 \u0639\u0628\u062f \u0623\u0633\u0648\u062f \u062d\u0628\u0634\u064a \u0645\u0646 \u0623\u0647\u0644 \u062e\u064a\u0628\u0631 \u0643\u0627\u0646 \u0641\u064a \u063a\u0646\u0645 \u0644\u0633\u064a\u062f\u0647\u060c \u0641\u0644\u0645\u0627 \u0631\u0623\u0649 \u0623\u0647\u0644 \u062e\u064a\u0628\u0631 \u0642\u062f \u0623\u062e\u0630\u0648\u0627 \u0627\u0644\u0633\u0644\u0627\u062d \u0648\u0633\u0623\u0644\u0647\u0645: \u0645\u0627\u062a\u0631\u064a\u062f\u0648\u0646\u061f \u0642\u0627\u0644\u0648\u0627: \u0646\u0642\u0627\u062a\u0644 \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u064a\u0632\u0639\u0645 \u0623\u0646\u0647 \u0646\u0628\u064a\u060c \u0641\u0648\u0642\u0639 \u0641\u064a \u0646\u0641\u0633\u0647 \u0630\u0643\u0631 \u0627\u0644\u0646\u0628\u064a\u060c \u0641\u0623\u0642\u0628\u0644 \u0628\u063a\u0646\u0645\u0647 \u0627\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0642\u0627\u0644: \u0645\u0627\u0630\u0627 \u062a\u0642\u0648\u0644\u061f \u0648\u0645\u0627\u062a\u062f\u0639\u0648 \u0625\u0644\u064a\u0647\u061f \u0642\u0627\u0644: \u0623\u062f\u0639\u0648\u0627 \u0627\u0644\u0649 \u0627\u0644\u0627\u0633\u0644\u0627\u0645 \u0648\u0623\u0646 \u062a\u0634\u0647\u062f \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u0623\u0646\u064a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0648\u0623\u0644\u0627 \u0646\u0639\u0628\u062f \u0625\u0644\u0627 \u0627\u0644\u0644\u0647\u060c \u0642\u0627\u0644 \u0627\u0644\u0639\u0628\u062f: \u0641\u0645\u0627\u0644\u064a \u0625\u0646 \u0634\u0647\u062f\u062a \u0648\u0622\u0645\u0646\u062a \u0628\u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0642\u0627\u0644: \u0644\u0643 \u0627\u0644\u062c\u0646\u0629 \u0627\u0646 \u0645\u062a \u0639\u0644\u0649 \u0630\u0644\u0643\u060c \u0641\u0623\u0633\u0644\u0645 \u062b\u0645 \u0642\u0627\u0644: \u064a\u0627\u0646\u0628\u064a \u0627\u0644\u0644\u0647: \u0625\u0646 \u0647\u0630\u0647 \u0627\u0644\u063a\u0646\u0645 \u0639\u0646\u062f\u064a \u0623\u0645\u0627\u0646\u0629 \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0623\u062e\u0631\u062c\u0647\u0627 \u0645\u0646 \u0639\u0646\u062f\u0643 \u0648\u0627\u0631\u0645\u0647\u0627 \u0628\u0640 \u0627\u0644\u062d\u0635\u0628\u0627\u0621 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u064a\u0624\u062f\u064a \u0639\u0646\u0643 \u0623\u0645\u0627\u0646\u062a\u0643\u060c \u0641\u0641\u0639\u0644\u060c \u0641\u0631\u062c\u0639\u062a \u0627\u0644\u063a\u0646\u0645 \u0627\u0644\u0649 \u0633\u064a\u062f\u0647\u0627 \u0641\u0639\u0644\u0645 \u0627\u0644\u064a\u0647\u0648\u062f\u064a \u0623\u0646 \u063a\u0644\u0627\u0645\u0647 \u0642\u062f \u0623\u0633\u0644\u0645\u060c \u0641\u0642\u0627\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u064a \u0627\u0644\u0646\u0627\u0633 \u0641\u0648\u0639\u0638\u0647\u0645 \u0648\u062d\u0636\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u062f \u0641\u0644\u0645\u0627 \u0627\u0644\u062a\u0642\u0649 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0648\u0627\u0644\u064a\u0647\u0648\u062f \u0642\u062a\u0644 -\u0641\u064a\u0645\u0646 \u0642\u062a\u0644- \u0627\u0644\u0639\u0628\u062f \u0627\u0644\u0627\u0633\u0648\u062f \u0648\u0627\u062d\u062a\u0645\u0644\u0647 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0627\u0644\u0649 \u0645\u0639\u0633\u0643\u0631\u0647\u0645\u060c \u0641\u0623\u062f\u062e\u0644 \u0641\u064a \u0627\u0644\u0641\u0633\u0637\u0627\u0637 \u0641\u0632\u0639\u0645\u0648\u0627 \u0623\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0637\u0644\u0639 \u0641\u064a \u0627\u0644\u0641\u0633\u0637\u0627\u0637\u060c \u062b\u0645 \u0623\u0642\u0628\u0644 \u0639\u0644\u0649 \u0623\u0635\u062d\u0627\u0628\u0647 \u0648\u0642\u0627\u0644: \u0644\u0642\u062f \u0623\u0643\u0631\u0645 \u0627\u0644\u0644\u0647 \u0647\u0630\u0627 \u0627\u0644\u0639\u0628\u062f \u0648\u0633\u0627\u0642\u0647 \u0627\u0644\u0649 \u062e\u064a\u0628\u0631\u060c \u0648\u0644\u0642\u062f \u0631\u0623\u064a\u062a \u0639\u0646\u062f \u0631\u0627\u0633\u0647 \u0627\u062b\u0646\u062a\u064a\u0646 \u0645\u0646 \u0627\u0644\u062d\u0648\u0631 \u0627\u0644\u0639\u064a\u0646\u060c \u0648\u0644\u0645 \u064a\u0635\u0644 \u0644\u0644\u0647 \u0633\u062c\u062f\u0629 \u0642\u0637.",null)
