B.aSm=new A.a("\u0639\u0635\u0645\u062a\u0647\u0627 \u0645\u0646 \u0627\u0644\u062f\u062c\u0627\u0644 \u0648\u0627\u0644\u0637\u0627\u0639\u0648\u0646 \u0628\u0628\u0631\u0643\u062a\u0647 \ufdfa: \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0642\u064a\u0636 \u0644\u0647\u0627 \u0645\u0644\u0627\u0626\u0643\u0629 \u064a\u062d\u0631\u0633\u0648\u0646\u0647\u0627\u060c \u0641\u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u062f\u062c\u0627\u0644 \u0625\u0644\u064a\u0647\u0627 \u0633\u0628\u064a\u0644\u0627\u064b\u060c \u0628\u0644 \u064a\u0644\u0642\u0649 \u0625\u0644\u064a\u0647 \u0628\u0625\u062e\u0648\u0627\u0646\u0647 \u0645\u0646 \u0627\u0644\u0643\u0641\u0627\u0631 \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646\u060c \u0643\u0645\u0627 \u0623\u0646 \u0645\u0646 \u0644\u0648\u0627\u0632\u0645 \u062f\u0639\u0627\u0621 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0627\u0644\u0635\u062d\u0629 \u0648\u0631\u0641\u0639 \u0627\u0644\u0648\u0628\u0627\u0621 \u0623\u0644\u0627 \u064a\u0646\u0632\u0644 \u0628\u0647\u0627 \u0627\u0644\u0637\u0627\u0639\u0648\u0646\u060c \u0643\u0645\u0627 \u0623\u062e\u0628\u0631 \u0628\u0630\u0644\u0643 \u0627\u0644\u0645\u0639\u0635\u0648\u0645 \ufdfa.",null)
B.aZM=new A.a("\u0641\u0636\u064a\u0644\u0629 \u0627\u0644\u0635\u0628\u0631 \u0639\u0644\u0649 \u0634\u062f\u062a\u0647\u0627: \u0641\u0642\u062f \u0648\u0639\u062f \u0627\u0644\u0646\u0628\u064a \ufdfa \u0645\u0646 \u0635\u0628\u0631 \u0639\u0644\u0649 \u0634\u062f\u0629 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0648\u0636\u064a\u0642 \u0639\u064a\u0634\u0647\u0627 \u0628\u0627\u0644\u0634\u0641\u0627\u0639\u0629 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0641\u0639\u0646 \u0633\u0639\u062f \u0628\u0646 \u0623\u0628\u064a \u0648\u0642\u0627\u0635 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0627\u0644: \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u062e\u064a\u0631 \u0644\u0647\u0645 \u0644\u0648 \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0644\u0645\u0648\u0646 \u0644\u0627 \u064a\u062f\u0639\u0647\u0627 \u0623\u062d\u062f \u0631\u063a\u0628\u0629 \u0639\u0646\u0647\u0627 \u0625\u0644\u0627 \u0623\u0628\u062f\u0644 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u0627 \u0645\u0646 \u0647\u0648 \u062e\u064a\u0631 \u0645\u0646\u0647\u060c \u0648\u0644\u0627 \u064a\u062b\u0628\u062a \u0623\u062d\u062f \u0639\u0644\u0649 \u0644\u0623\u0648\u0627\u0626\u0647\u0627 \u0648\u062c\u0647\u062f\u0647\u0627 \u0625\u0644\u0627 \u0643\u0646\u062a \u0644\u0647 \u0634\u0641\u064a\u0639\u0627 \u0623\u0648 \u0634\u0647\u064a\u062f\u0627 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629.",null)
B.b_q=new A.a("\u0641\u0636\u064a\u0644\u0629 \u0627\u0644\u0645\u0648\u062a \u0641\u064a\u0647\u0627: \u0641\u0639\u0646 \u0627\u0628\u0646 \u0639\u0645\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0627\u0644: \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \u0645\u0646 \u0627\u0633\u062a\u0637\u0627\u0639 \u0623\u0646 \u064a\u0645\u0648\u062a \u0628\u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0641\u0644\u064a\u0645\u062a \u0628\u0647\u0627\u060c \u0641\u0625\u0646\u064a \u0623\u0634\u0641\u0639 \u0644\u0645\u0646 \u064a\u0645\u0648\u062a \u0628\u0647\u0627 \u060c \u0648\u0643\u0627\u0646 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u064a\u062f\u0639\u0648 \u0628\u0647\u0630\u0627 \u0627\u0644\u062f\u0639\u0627\u0621: \u0627\u0644\u0644\u0647\u0645 \u0627\u0631\u0632\u0642\u0646\u064a \u0634\u0647\u0627\u062f\u0629 \u0641\u064a \u0633\u0628\u064a\u0644\u0643\u060c \u0648\u0627\u062c\u0639\u0644 \u0645\u0648\u062a\u064a \u0641\u064a \u0628\u0644\u062f \u0631\u0633\u0648\u0644\u0643 \ufdfa \u060c \u0648\u0642\u062f \u0627\u0633\u062a\u062c\u0627\u0628 \u0627\u0644\u0644\u0647 \u0644\u0644\u0641\u0627\u0631\u0648\u0642 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0641\u0627\u0633\u062a\u0634\u0647\u062f \u0641\u064a \u0645\u062d\u0631\u0627\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0647\u0648 \u064a\u0624\u0645 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u0635\u0644\u0627\u0629 \u0627\u0644\u0641\u062c\u0631.",null)
