B.bq7=new A.e("15","\u0645\u0639\u0627\u0645\u0644\u0629 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0644\u0644\u0631\u0645\u0627\u0629",null)
B.aRH=new A.a("\u0625\u0646 \u0627\u0644\u0631\u0645\u0627\u0629 \u0627\u0644\u0630\u064a\u0646 \u0623\u062e\u0637\u0623\u0648\u0627 \u0627\u0644\u0627\u062c\u062a\u0647\u0627\u062f \u0641\u064a \u063a\u0632\u0648\u0629 \u0623\u062d\u062f \u0644\u0645 \u064a\u062e\u0631\u062c\u0647\u0645 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u062e\u0627\u0631\u062c \u0627\u0644\u0635\u0641\u060c \u0648\u0644\u0645 \u064a\u0642\u0644 \u0644\u0647\u0645 \u0625\u0646\u0643\u0645 \u0644\u0627\u062a\u0635\u0644\u062d\u0648\u0646 \u0644\u0634\u064a\u0621 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0628\u0639\u062f\u0645\u0627 \u0628\u062f\u0627 \u0645\u0646\u0643\u0645 \u0641\u064a \u0627\u0644\u062a\u062c\u0631\u0628\u0629 \u0645\u0646 \u0627\u0644\u0646\u0642\u0635 \u0648\u0627\u0644\u0636\u0639\u0641\u060c \u0628\u0644 \u0642\u0628\u0644 \u0636\u0639\u0641\u0647\u0645 \u0647\u0630\u0627 \u0641\u064a \u0631\u062d\u0645\u0629 \u0648\u0639\u0641\u0648 \u0648\u0641\u064a \u0633\u0645\u0627\u062d\u0629 \u062b\u0645 \u0634\u0645\u0644 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0628\u0631\u0639\u0627\u064a\u062a\u0647 \u0648\u0639\u0641\u0648\u0647 \u062c\u0645\u064a\u0639 \u0627\u0644\u0630\u064a\u0646 \u0627\u0634\u062a\u0631\u0643\u0648\u0627 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u063a\u0632\u0648\u0629 \u0631\u063a\u0645 \u0645\u0627\u0648\u0642\u0639 \u0645\u0646 \u0628\u0639\u0636\u0647\u0645 \u0645\u0646 \u0623\u062e\u0637\u0627\u0621 \u062c\u0633\u064a\u0645\u0629\u060c \u0648\u0645\u0627\u062a\u0631\u062a\u0628 \u0639\u0644\u064a\u0647 \u0645\u0646 \u062e\u0633\u0627\u0626\u0631 \u0641\u0627\u062f\u062d\u0629 \u0641\u0639\u0641\u0627 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0639\u0641\u0648\u0627\u064b \u063a\u0633\u0644 \u0628\u0647 \u062e\u0637\u0627\u064a\u0627\u0647\u0645 \u0648\u0645\u062d\u0627 \u0628\u0647 \u0622\u062b\u0627\u0631 \u062a\u0644\u0643 \u0627\u0644\u062e\u0637\u0627\u064a\u0627\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0635\u064e\u062f\u064e\u0642\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0639\u0652\u062f\u064e\u0647\u064f \u0625\u0650\u0630\u0652 \u062a\u064e\u062d\u064f\u0633\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u0652 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650 \u062d\u064e\u062a\u0651\u064e\u0649 \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0634\u0650\u0644\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u062a\u064e\u0646\u064e\u0627\u0632\u064e\u0639\u0652\u062a\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0623\u064e\u0645\u0652\u0631\u0650 \u0648\u064e\u0639\u064e\u0635\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0623\u064e\u0631\u064e\u0627\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u062b\u064f\u0645\u0651\u064e \u0635\u064e\u0631\u064e\u0641\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0644\u0650\u064a\u064e\u0628\u0652\u062a\u064e\u0644\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0639\u064e\u0641\u064e\u0627 \u0639\u064e\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0641\u064e\u0636\u0652\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e - \u0633\u0648\u0631\u0629 \u0622\u0644 \u0639\u0645\u0631\u0627\u0646 \u060c\u0648\u0647\u0646\u0627\u0643 \u0623\u0645\u0631 \u0645\u0647\u0645 \u064a\u062a\u0635\u0644 \u0628\u0647\u0630\u0627 \u0627\u0644\u0639\u0641\u0648 \u0642\u062f \u064a\u062a\u0631\u0643 \u0623\u062b\u0631\u0627\u064b \u0641\u064a \u0646\u0641\u0648\u0633\u0647\u0645 \u064a\u0639\u0648\u0642\u0647\u0627 \u0628\u0639\u0636 \u0627\u0644\u0634\u064a\u0621 \u0630\u0644\u0643 \u0647\u0648 \u0645\u0648\u0642\u0641 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0645\u0627 \u062d\u062f\u062b \u0645\u0646\u0647\u0645 \u0625\u0646\u0647\u0645 \u064a\u0634\u0639\u0631\u0648\u0646 \u0623\u0646 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0647\u0648 \u0648\u062d\u062f\u0647 \u0627\u0644\u0630\u064a \u062a\u062d\u0645\u0644 \u0646\u062a\u064a\u062c\u0629 \u062a\u0644\u0643 \u0627\u0644\u0623\u062e\u0637\u0627\u0621\u060c \u0641\u0644\u0627\u0628\u062f \u0623\u0646 \u064a\u0646\u0627\u0644\u0648\u0627 \u0645\u0646\u0647 \u0639\u0641\u0648\u0627\u064b \u062a\u0637\u064a\u0628 \u0628\u0647 \u0646\u0641\u0648\u0633\u0647\u0645 \u0648\u062a\u062a\u0645 \u0628\u0647 \u0646\u0639\u0645\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0644\u0647\u0630\u0627 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0646\u0628\u064a\u0647 \ufdfa \u0628\u0623\u0646 \u064a\u0639\u0641\u0648 \u0639\u0646\u0647\u0645\u060c \u0648\u062d\u062b\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0627\u0633\u062a\u063a\u0641\u0627\u0631 \u0644\u0647\u0645 \u0643\u0645\u0627 \u0623\u0645\u0631\u0647 \u0623\u0646 \u064a\u0623\u062e\u0630 \u0631\u0623\u064a\u0647\u0645 \u0648\u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0625\u0644\u0649 \u0645\u0634\u0648\u0631\u062a\u0647\u0645 \u0648\u0644\u0627\u064a\u062c\u0639\u0644 \u0645\u0627\u062d\u062f\u062b \u0635\u0627\u0631\u0641\u0627\u064b \u0644\u0647 \u0639\u0646 \u0627\u0644\u0627\u0633\u062a\u0641\u0627\u062f\u0629 \u0645\u0646 \u062e\u0628\u0631\u0627\u062a\u0647\u0645 \u0648\u0645\u0634\u0648\u0631\u062a\u0647\u0645\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \u0641\u064e\u0628\u0650\u0645\u064e\u0627 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u0646\u0652\u062a\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064f\u0646\u0652\u062a\u064e \u0641\u064e\u0638\u0651\u064b\u0627 \u063a\u064e\u0644\u0650\u064a\u0638\u064e \u0627\u0644\u0652\u0642\u064e\u0644\u0652\u0628\u0650 \u0644\u0627\u0646\u0652\u0641\u064e\u0636\u0651\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u062d\u064e\u0648\u0652\u0644\u0650\u0643\u064e \u0641\u064e\u0627\u0639\u0652\u0641\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0634\u064e\u0627\u0648\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0623\u064e\u0645\u0652\u0631\u0650 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0632\u064e\u0645\u0652\u062a\u064e \u0641\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0648\u064e\u0643\u0651\u0650\u0644\u0650\u064a\u0646\u064e - \u0633\u0648\u0631\u0629 \u0622\u0644 \u0639\u0645\u0631\u0627\u0646",null)
